#!/usr/bin/env bash
# Predict the fork's CI mail before a push: GitHub evaluates workflow files
# from the pushed ref's own tree, so a branch cut before the ci.yaml hardening
# still carries its old triggers — and on a fork a SignPath job can only fail
# at startup, mailing the owner one failure per push.
#
# Usage: check_fork_ci_noise.sh <branch>|<sha>
# Exit codes: 0 quiet, 1 the ref's tree fires a fork-failing run,
# 125 not applicable (ref is not a commit).
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u
export MSYS_NO_PATHCONV=1  # git show "$ref:$file" would lose the colon to MSYS
ref=${1:-}
[ -n "$ref" ] || { printf 'usage: %s <branch>|<sha>\n' "$0" >&2; exit 2; }
git rev-parse --verify --quiet "$ref^{commit}" >/dev/null || {
    printf 'SKIP  fork CI noise (%s is not a commit)\n' "$ref"
    exit 125
}

blast=0
for file in $(git ls-tree -r --name-only "$ref" -- .github/workflows | grep -E '\.ya?ml$'); do
    body=$(git show "$ref:$file")
    case "$body" in
        *"branches: ['**']"*)
            printf 'NOISE %s: push trigger matches every branch; every push to the fork mails a failure\n' "$file"
            blast=1
            ;;
    esac
    if printf '%s\n' "$body" | grep -q 'build-and-sign.yaml' &&
       ! printf '%s\n' "$body" | grep -q "github.repository == 'EasyIME/PIME'"; then
        printf 'NOISE %s: calls the SignPath workflow without a fork gate; startup failure on the fork\n' "$file"
        blast=1
    fi
done

if [ "$blast" -eq 1 ]; then
    printf 'Remediation: rebase %s onto a state carrying the hardened ci.yaml (push filter\n' "$ref"
    printf 'plus the github.repository gate). A product branch keeps the upstream triggers,\n'
    printf 'where the mails are inherent to pushing — push those only on deliberate deliveries.\n'
    exit 1
fi
printf 'QUIET %s fires no fork-failing workflow\n' "$ref"
